    [t('«Kolumbiya» shattli','Шаттл «Колумбия»','Space Shuttle Columbia'), t('Orbitaga chiqqan birinchi shattl; Yang unda ikki marta — STS-1 va STS-9 parvozlarida qo‘mondon bo‘lgan.','Первый шаттл, вышедший на орбиту; Янг дважды командовал им — в полётах STS-1 и STS-9.','The first Shuttle to reach orbit; Young commanded it twice, on STS-1 and STS-9.'), null],
    [t('«Gemini» kemasi','Корабль «Джемини»','Gemini spacecraft'), t('Yang «Gemini» ning birinchi boshqariladigan parvozida uchgan va keyinroq unga qo‘mondonlik qilgan.','Янг летал в первом пилотируемом полёте «Джемини», а позже командовал этим кораблём.','Young flew on the first crewed Gemini flight and later commanded one.'), null]
